-- ==============================================================
-- TURNOS DE AGOSTO 2026 — Servicio Urgencias (id 4)
-- Reproduce en una BD nueva la ejecución "Planificación: Rotativa 2026"
-- del ambiente anterior, tal como quedó exportada en
-- turnos_2026_8_servicio_4.csv (945 turnos, IDs 6966–8221).
--
-- Qué hace, en orden:
--   1. Crea la ejecución de planificación (planificacion_ejecucion) de la
--      vigencia 2026-07-31 → 2026-08-31 para la planificación 'Rotativa 2026'.
--   2. Inserta los 945 turnos CON SUS IDs ORIGINALES (INSERT IGNORE =
--      re-ejecutable; el AUTO_INCREMENT de Turnos queda después en 8222).
--      Funcionario, puesto y rotativa se resuelven por subconsulta (nunca por
--      id duro): si un RUT no existe en Funcionario, el turno queda vacante.
--   3. Escribe la bitácora que la exportación usa para rotular el origen:
--      GENERACION_TURNO ('Planificación: Rotativa 2026') para todos, y
--      ASIGNACION_MANUAL posterior para los 2 turnos asignados a mano
--      (7332 → RUT 30000078, 7500 → RUT 17599096), igual que en el CSV.
--
-- Requisitos previos: poblado_urgencias_gestionturnos.sql y la migración V2.
-- El turno 7500 pertenece al RUT real 17599096: si ese funcionario aún no
-- está dado de alta, el turno queda vacante (la verificación final lo avisa).
--
-- Cargar SIEMPRE vía el wrapper (fija utf8mb4):
--   bash scripts/mysql.sh < BaseDatosMySQL/despliegue/turnos_agosto2026_urgencias.sql
-- ==============================================================

USE gestionturnos;
SET NAMES utf8mb4;

SET @plan = (SELECT id_planificacion FROM planificacion WHERE nombre = 'Rotativa 2026' AND id_servicio = 4 LIMIT 1);

-- 1. Ejecución de la planificación (idempotente)
INSERT INTO planificacion_ejecucion
    (id_planificacion, id_servicio, fecha_inicio_rotativa, fecha_inicio_efectiva,
     fecha_fin_efectiva, fecha_generacion, id_funcionario_actor, estado, ids_reglas_aplicadas)
SELECT @plan, 4, '2026-07-27', '2026-07-31', '2026-08-31', '2026-07-27 09:00:00', NULL, 'ACTIVA', '1'
WHERE @plan IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM planificacion_ejecucion
                   WHERE id_planificacion = @plan AND fecha_inicio_efectiva = '2026-07-31'
                     AND fecha_fin_efectiva = '2026-08-31' AND estado = 'ACTIVA');

SET @ej    = (SELECT id_ejecucion FROM planificacion_ejecucion
               WHERE id_planificacion = @plan AND fecha_inicio_efectiva = '2026-07-31'
                 AND fecha_fin_efectiva = '2026-08-31' AND estado = 'ACTIVA' LIMIT 1);
SET @dia   = (SELECT id_tipo_turno FROM tipo_turno WHERE id_servicio = 4 AND nombre = 'Dia'   LIMIT 1);
SET @noche = (SELECT id_tipo_turno FROM tipo_turno WHERE id_servicio = 4 AND nombre = 'Noche' LIMIT 1);

-- 2. Los 945 turnos (IDs explícitos; INSERT IGNORE los hace re-ejecutables)
INSERT IGNORE INTO Turnos
    (id_turno, dia_inicio_turno, dia_final_turno, hora_inicio, hora_fin,
     ID_FUNCIONARIO, id_servicio, id_puesto, id_rotativa, id_tipo_turno, id_ejecucion, eliminado)
VALUES
