-- 3a. Bitácora de generación (una por turno importado; el export toma de aquí
--     el rótulo 'Rotativa habitual · Planificación: Rotativa 2026')
INSERT INTO Bitacora_eventos
    (Tipo_evento, Motivo, Observaciones, Fecha_inicio_afectada, Fecha_fin_afectada,
     Fecha_modificacion, Activo, ID_TURNO, ID_FUNCIONARIO)
SELECT 'GENERACION_TURNO', 'Planificación: Rotativa 2026', 'Turno generado (importación de la vigencia de agosto 2026)',
       TIMESTAMP(t.dia_inicio_turno, t.hora_inicio), TIMESTAMP(t.dia_final_turno, t.hora_fin),
       '2026-07-27 09:00:00', b'1', t.id_turno, NULL
FROM Turnos t
WHERE t.id_ejecucion = @ej
  AND NOT EXISTS (SELECT 1 FROM Bitacora_eventos b
                   WHERE b.ID_TURNO = t.id_turno AND b.Tipo_evento = 'GENERACION_TURNO');

-- 3b. Los 2 turnos asignados a mano (evento posterior: el export elige el más reciente)
INSERT INTO Bitacora_eventos
    (Tipo_evento, Motivo, Observaciones, Fecha_modificacion, Activo, ID_TURNO, ID_FUNCIONARIO)
SELECT 'ASIGNACION_MANUAL', 'Asignación manual de funcionario', 'Importado: asignación manual del ambiente anterior',
       '2026-07-28 09:00:00', b'1', t.id_turno, t.ID_FUNCIONARIO
FROM Turnos t
WHERE t.id_turno IN (7332, 7500)
  AND NOT EXISTS (SELECT 1 FROM Bitacora_eventos b
                   WHERE b.ID_TURNO = t.id_turno AND b.Tipo_evento = 'ASIGNACION_MANUAL');

-- ==============================================================
-- VERIFICACIÓN (esperado: total=945, dia=465, noche=480, vacantes=41,
-- sin_puesto=0, manuales=2, y turno_7500_asignado=1 si el RUT 17599096
-- ya está dado de alta como funcionario)
-- ==============================================================
SELECT
  (SELECT COUNT(*) FROM Turnos WHERE id_ejecucion = @ej)                                        AS total,
  (SELECT COUNT(*) FROM Turnos WHERE id_ejecucion = @ej AND id_tipo_turno = @dia)               AS dia,
  (SELECT COUNT(*) FROM Turnos WHERE id_ejecucion = @ej AND id_tipo_turno = @noche)             AS noche,
  (SELECT COUNT(*) FROM Turnos WHERE id_ejecucion = @ej AND ID_FUNCIONARIO IS NULL)             AS vacantes,
  (SELECT COUNT(*) FROM Turnos WHERE id_ejecucion = @ej AND id_puesto IS NULL)                  AS sin_puesto,
  (SELECT COUNT(*) FROM Bitacora_eventos WHERE Tipo_evento = 'ASIGNACION_MANUAL'
     AND ID_TURNO IN (7332, 7500))                                                              AS manuales,
  (SELECT COUNT(*) FROM Turnos WHERE id_turno = 7500 AND ID_FUNCIONARIO IS NOT NULL)            AS turno_7500_asignado;
